const initialQuestions=[{id:1,name:'Bác Minh',initials:'M',age:68,category:'Điện thoại',title:'Gọi video cho cháu trên Zalo thế nào?',body:'Cháu nội tôi vừa vào Sài Gòn học đại học. Tôi muốn gọi video để nhìn thấy cháu mà chưa biết bấm vào đâu. Nhờ các cháu chỉ giúp từng bước.',time:'15 phút trước',answers:[{id:'a1',name:'Minh Anh',initials:'MA',body:'Dạ, bác làm theo 3 bước này nhé:\n1. Mở Zalo, chạm vào tên cháu trong danh sách tin nhắn.\n2. Nhìn lên góc trên bên phải, bấm vào hình chiếc máy quay.\n3. Chờ cháu bắt máy. Nếu màn hình đen, bác bấm “Cho phép” khi Zalo hỏi dùng camera.\nBác thử xong nhắn cháu biết với nhé!',likes:12,reviewed:true}]},{id:2,name:'Cô Hương',initials:'H',age:64,category:'An toàn',title:'Có người gọi xin mã OTP, cô có nên đọc không?',body:'Sáng nay có người xưng là nhân viên ngân hàng, bảo cô đọc mã OTP vừa nhận để “cập nhật tài khoản”. Cô chưa đọc. Giờ cô nên làm gì?',time:'35 phút trước',answers:[{id:'a2',name:'Tuấn Anh',initials:'TA',body:'Cô làm đúng rồi ạ! Ngân hàng không bao giờ gọi điện xin mã OTP.\n• Cô tắt máy, không đọc mã và không bấm vào đường link lạ.\n• Gọi tổng đài ngân hàng theo số in ở mặt sau thẻ để báo lại.\n• Nếu lỡ đọc mã rồi, cô gọi ngân hàng khóa tài khoản ngay.',likes:21,reviewed:true}]},{id:3,name:'Bác Thành',initials:'T',age:71,category:'Điện thoại',title:'Chữ trên điện thoại bé quá, phóng to thế nào?',body:'Đọc tin nhắn tôi cứ phải nheo mắt mãi. Máy tôi là Samsung. Có cách nào cho chữ to hẳn lên không các cháu?',time:'1 giờ trước',answers:[]},{id:4,name:'Cô Mai',initials:'M',age:63,category:'Ứng dụng',title:'Gửi ảnh hoa qua Zalo cho bạn thế nào?',body:'Mấy hôm nay hồng trong vườn nở rộ, cô chụp được mấy tấm đẹp lắm. Muốn gửi cho hội bạn mà loay hoay mãi chưa được.',time:'2 giờ trước',answers:[]},{id:5,name:'Cô Lan',initials:'L',age:66,category:'Ứng dụng',title:'Đặt lịch khám qua ứng dụng bệnh viện có khó không?',body:'Con gái cài cho cô ứng dụng của bệnh viện để đặt lịch khám, nhưng cô chưa dám bấm vì sợ đặt nhầm ngày.',time:'Hôm qua',answers:[{id:'a3',name:'Tuấn Anh',initials:'TA',body:'Không khó đâu cô ạ. Cô mở ứng dụng, chọn “Đặt lịch khám”, rồi lần lượt chọn chuyên khoa, ngày và giờ. Trước khi bấm “Xác nhận”, màn hình luôn hiện lại thông tin để cô kiểm tra, nhầm thì cô cứ bấm “Quay lại”.\nCô muốn cháu chỉ trực tiếp thì nhắn cháu nhé.',likes:9,reviewed:true}]}];
