const defaultState=()=>({view:'experience',screen:'home',role:'senior',font:0,filter:'Tất cả',search:'',questionId:1,productId:'tea',chatId:'huong',points:120,redeemed:false,questions:structuredClone(initialQuestions),likes:[],helpful:[],friends:[],messages:{huong:[{me:false,text:'Chào bác Minh! Thấy bác cũng mê trồng hoa. Vườn nhà bác dạo này có gì đẹp không?'},{me:true,text:'Chào cô Hương! Mấy chậu hoa giấy nhà tôi đang nở đỏ cả ban công, hôm nào tôi chụp gửi cô xem.'},{me:false,text:'Hay quá! Nhớ gửi nhé, tôi đang định xin một cành về giâm.'}],minhanh:[{me:false,text:'Cháu chào bác ạ! Bác gọi video cho bạn Khoa được chưa ạ? Có chỗ nào chưa rõ bác cứ nhắn cháu nhé.'}]},newPosts:[],familyOrder:null,joined:false,support:null,helperId:'minhanh',supportIssue:'Gọi video',supportLandmark:'Hồ Hoàn Kiếm, Hà Nội',notes:[],unread:2,typing:null});
let state=defaultState();
try{const saved=JSON.parse(localStorage.getItem('anvui-demo-v1'));if(saved)state={...state,...saved,view:'experience',screen:'home',search:'',filter:'Tất cả',typing:null};}catch{}
{const v=new URLSearchParams(location.search).get('view');if(['business','launch','campaign'].includes(v))state.view=v;}
if(new URLSearchParams(location.search).has('app'))document.body.classList.add('phone-only');
const isIOS=/iPhone|iPad|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
const isStandalone=navigator.standalone===true||!!window.matchMedia?.('(display-mode: standalone)').matches;
if(isStandalone||(document.body.classList.contains('phone-only')&&window.matchMedia?.('(max-width: 500px)').matches)){document.body.classList.add('phone-only','app-native');state.view='experience'}
function installDismissed(){try{return localStorage.getItem('anvui-install-hint')==='hidden'}catch{return false}}
function installBanner(){if(!isIOS||isStandalone||installDismissed())return '';return `<div class="install-banner">${icon('download')}<div><strong>Đặt An Vui ra màn hình chính</strong><p>Mở như một ứng dụng, không cần App Store.</p><div class="install-banner-actions"><button class="primary" data-action="install">Xem cách làm</button><button class="text-link" data-action="install-dismiss">Để sau</button></div></div></div>`}
function pushNav(){try{const cur=history.state;if(cur&&cur.view===state.view&&cur.screen===state.screen)return;history.pushState({view:state.view,screen:state.screen},'')}catch{}}
let toastTimer,installPrompt,recognition;
const $=s=>document.querySelector(s);
function todayLabel(){try{const s=new Date().toLocaleDateString('vi-VN',{weekday:'long',day:'numeric',month:'numeric'});return s.charAt(0).toUpperCase()+s.slice(1)}catch{return 'Hôm nay'}}
let liveQueue=[];
function later(fn,ms){const job={fn,t:null};if(window.AV_LIVE!==false)job.t=setTimeout(()=>{liveQueue=liveQueue.filter(j=>j!==job);fn()},ms);liveQueue.push(job)}
function flushLive(){while(liveQueue.length){const j=liveQueue.shift();clearTimeout(j.t);j.fn()}}
function cancelLive(){liveQueue.forEach(j=>clearTimeout(j.t));liveQueue=[];document.querySelectorAll('.live-banner').forEach(el=>el.remove())}
function syncBell(){document.querySelector('[data-action="notifications"] .dot')?.toggleAttribute('hidden',!(state.unread>0))}
function ago(t){const m=Math.floor((Date.now()-t)/60000);return m<1?'Vừa xong':m<60?`${m} phút trước`:`${Math.floor(m/60)} giờ trước`}
function pushNote(n){state.notes=[{...n,time:Date.now()},...(state.notes||[])].slice(0,8);state.unread=(state.unread||0)+1;persist();syncBell();if(state.role==='senior'&&state.view==='experience')liveBanner(n)}
function noteHTML(n){const btn=n.question?`<button class="secondary" data-notification-question="${Number(n.question)}">Xem câu trả lời</button>`:n.screen?`<button class="secondary" data-live-screen="${esc(n.screen)}">${esc(n.cta||'Xem chi tiết')}</button>`:'';return `<div class="modal-feature">${avatar(n.initials,n.color,n.who)}<div><strong>${esc(n.title)}</strong><p>${esc(n.text)} · ${ago(n.time)}</p>${btn}</div></div>`}
function liveBanner(n){const host=$('.phone');if(!host)return;host.querySelectorAll('.live-banner').forEach(el=>el.remove());const el=document.createElement('button');el.type='button';el.className='live-banner';if(n.question)el.dataset.notificationQuestion=n.question;else if(n.screen)el.dataset.liveScreen=n.screen;el.innerHTML=`<span class="live-app">${icon('leaf')} AN VUI <time>bây giờ</time></span><span class="live-body">${avatar(n.initials,n.color,n.who)}<span><b>${esc(n.title)}</b><small>${esc(n.text)}</small></span></span>`;host.appendChild(el);requestAnimationFrame(()=>requestAnimationFrame(()=>el.classList.add('show')));setTimeout(()=>{el.classList.remove('show');setTimeout(()=>el.remove(),450)},7000)}
const AUTO_ANSWERS=[
 [/đèn pin|den pin|flash/,'Dạ cháu chào bác! Bác làm theo cháu nhé:\n1. Vuốt từ góc trên bên phải màn hình xuống.\n2. Bác sẽ thấy biểu tượng hình đèn pin, bấm vào là đèn sáng.\n3. Muốn tắt, bác vuốt xuống và bấm lại đúng biểu tượng đó.\nMáy bác là Android thì vuốt từ cạnh trên xuống, cách làm y hệt ạ.'],
 [/otp|lừa|mật khẩu|ngân hàng|công an|trúng thưởng|chuyển tiền/,'Dạ bác ơi, bác làm đúng khi hỏi trước ạ!\n1. Mã OTP chỉ để bác tự nhập, tuyệt đối không đọc cho ai, kể cả người xưng là ngân hàng hay công an.\n2. Bác không bấm vào đường link lạ trong tin nhắn.\n3. Nếu lỡ đọc mã rồi, bác gọi ngay tổng đài ngân hàng in sau thẻ để khoá tài khoản.\nBác cứ chụp tin nhắn gửi cháu, cháu xem giúp có phải lừa đảo không ạ.'],
 [/zalo|video|gọi/,'Dạ cháu chào bác! Gọi video trên Zalo bác làm 3 bước thôi ạ:\n1. Mở Zalo, bấm vào tên người bác muốn gọi.\n2. Bấm biểu tượng máy quay ở góc trên bên phải.\n3. Đợi bên kia nhấc máy là hai bên nhìn thấy nhau.\nLần đầu máy hỏi quyền dùng camera, bác bấm “Cho phép” nhé.'],
 [/ảnh|hình|chụp/,'Dạ bác làm theo cháu nhé:\n1. Mở cuộc trò chuyện với người bác muốn gửi.\n2. Bấm biểu tượng bức ảnh ở cạnh ô nhập chữ.\n3. Chạm vào ảnh muốn gửi, rồi bấm nút Gửi màu xanh.\nMuốn gửi nhiều ảnh, bác chạm lần lượt từng ảnh trước khi bấm Gửi ạ.'],
 [/chữ|đọc|nhỏ|mắt/,'Dạ phóng to chữ dễ lắm bác ạ:\n1. Mở Cài đặt (biểu tượng bánh răng).\n2. Chọn “Màn hình & Độ sáng”, rồi “Cỡ chữ”.\n3. Kéo thanh trượt sang phải đến khi bác đọc thấy thoải mái.\nTrong An Vui, bác bấm nút “Aa” ở góc trên để đổi cỡ chữ nhanh ạ.'],
 [/wifi|wi-fi|mạng|internet/,'Dạ bác làm theo cháu nhé:\n1. Mở Cài đặt, chọn Wi‑Fi.\n2. Bấm vào tên mạng nhà mình (thường ghi ở mặt dưới cục phát).\n3. Nhập mật khẩu rồi bấm Kết nối.\nKhi thấy dấu tích bên cạnh tên mạng là xong ạ.'],
 [/pin|sạc|nóng/,'Dạ để máy đỡ tốn pin, bác thử 3 việc này nhé:\n1. Giảm độ sáng màn hình xuống khoảng một nửa.\n2. Vào Cài đặt → Pin, bật “Chế độ nguồn điện thấp”.\n3. Tắt những ứng dụng không dùng bằng cách vuốt từ dưới lên.\nBác nên dùng đúng dây sạc đi kèm máy cho an toàn ạ.']];
function autoAnswer(q){const t=(q.title+' '+q.body).toLowerCase();const hit=AUTO_ANSWERS.find(([re])=>re.test(t));return hit?hit[1]:'Dạ cháu chào bác! Cháu đọc câu hỏi của bác rồi ạ. Để chỉ đúng, bác giúp cháu 2 việc nhé:\n1. Chụp màn hình chỗ bác đang vướng (bấm cùng lúc nút nguồn và nút tăng âm lượng).\n2. Gửi ảnh đó cho cháu qua nút “Nhắn riêng cho Minh Anh” bên dưới.\nCháu xem xong sẽ chỉ bác từng bước ạ.'}
function simulateAnswer(id){later(()=>{if(!state.questions.some(q=>q.id===id))return;state.typing=id;if(state.screen==='question'&&state.questionId===id&&state.view==='experience')renderScreen()},2500);later(()=>{const q=state.questions.find(q=>q.id===id);state.typing=null;if(!q)return;const body=autoAnswer(q);q.answers.push({id:'answer-'+Date.now(),name:'Minh Anh',initials:'MA',body,likes:0,reviewed:true});persist();if(state.screen==='question'&&state.questionId===id&&state.view==='experience')renderScreen();pushNote({who:'Minh Anh',initials:'MA',color:'orange',title:'Minh Anh đã trả lời câu hỏi của bác',text:'“'+body.split('\n').slice(1,2).join('').replace(/^1\.\s*/,'').replace(/[.…!?\s]+$/,'')+'…”',question:id})},8000)}
function typingCard(){return `<div class="typing-card" role="status">${avatar('MA','orange','Minh Anh')}<span>Minh Anh đang soạn câu trả lời</span><span class="typing-dots" aria-hidden="true"><i></i><i></i><i></i></span></div>`}
function qrCard(){return `<button class="qr-card" data-action="qr" aria-label="Phóng to mã QR để mở An Vui trên điện thoại"><img src="assets/qr-app.svg" alt="" width="88" height="88"><span><b>Quét để dùng thử trên điện thoại</b><small>Mở camera, hướng vào mã. Không cần tải ứng dụng.</small></span>${icon('arrow')}</button>`}
function persist(){try{localStorage.setItem('anvui-demo-v1',JSON.stringify(state))}catch{}}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200)}
function avatar(initials,color='',name=''){const p=PEOPLE[name];return p&&p.photo?`<span class="avatar photo ${color}"><img src="assets/avatars/${p.photo}.webp" alt="" width="96" height="96" loading="lazy"></span>`:`<span class="avatar ${color}">${esc(initials)}</span>`}
function verified(){return `<span class="verified" title="Đã xác thực danh tính">${icon('badge')}</span>`}
function person(name,initials,detail,color=''){return `<div class="person-line">${avatar(initials,color,name)}<div class="person-info"><div class="person-name">${esc(name)}${verified()}</div><div class="person-detail">${esc(detail)}</div></div></div>`}
function screenTo(screen,fromHistory=false){state.screen=screen;state.search='';state.filter='Tất cả';state.view='experience';persist();if(!fromHistory)pushNav();render();$('#app-scroll')?.scrollTo(0,0)}
function switchRole(role){state.role=role;state.screen=role==='helper'?'questions':'home';state.search='';state.filter='Tất cả';persist();render();toast(role==='helper'?'Đã chuyển sang tài khoản Minh Anh':'Đã chuyển sang tài khoản bác Minh')}
function render(){const banner=document.querySelector('.phone .live-banner');document.querySelectorAll('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===state.view));$('#page').innerHTML=state.view==='experience'?experience():state.view==='business'?business():state.view==='campaign'?campaign():launch();if(state.view==='experience')renderScreen();else if(state.view==='business')updateCalculator();if(banner)$('.phone')?.appendChild(banner);}
function experience(){const helper=state.role==='helper';return `<section class="experience"><div class="hero-copy"><div class="eyebrow">CỘNG ĐỒNG CHO TUỔI VÀNG</div><h1>Thêm bạn.<br>Thêm niềm vui<br><em>mỗi ngày.</em></h1><p class="hero-description">Nơi cô bác hỏi điều chưa biết, kết bạn cùng sở thích, và luôn có một bạn trẻ kiên nhẫn chỉ cho từng bước.</p><div class="hero-actions"><button class="primary" data-action="onboarding">Xem An Vui hoạt động ${icon('arrow')}</button></div><div class="hero-trust">${icon('shield')} Tài khoản xác thực · Nội dung được kiểm duyệt</div>${qrCard()}</div><div class="phone-wrap"><div class="phone" aria-label="Ứng dụng An Vui trên điện thoại"><div class="phone-status"><span>9:41</span><span class="status-icons">${icon('signal')}${icon('wifi')}${icon('battery')}</span></div><div class="app-header"><div class="app-brand"><button class="zen-mark" data-action="about-zentech" aria-label="Zentech — nhóm phát triển An Vui"><img src="assets/zentech-mark.webp" alt="" width="30" height="30"></button><span class="brand-divider" aria-hidden="true"></span>${brandLockup()}</div><div class="app-header-actions"><button class="icon-button" data-action="font" aria-label="Đổi cỡ chữ" title="Đổi cỡ chữ">${icon('textsize')}</button><button class="icon-button" data-action="notifications" aria-label="Thông báo">${icon('bell')}<span class="dot" ${state.unread>0?'':'hidden'}></span></button><button class="avatar-button" data-screen="profile" aria-label="Tài khoản của bạn">${avatar(helper?'MA':'M',helper?'orange':'',helper?'Minh Anh':'Bác Minh')}</button></div></div><div id="app-scroll" class="app-scroll ${state.font===1?'large-text':state.font===2?'extra-large':''} ${state.compact?'compact':''}" tabindex="-1">${state.compact?'<div class="demo-strip">Bản thử nghiệm · Dữ liệu mẫu, không giao dịch thật</div>':''}<div class="app-content" id="app-content"></div></div><nav class="bottom-nav" aria-label="Điều hướng ứng dụng">${[['home','home','Trang chủ'],['questions','message','Hỏi đáp'],[helper?'rewards':'market',helper?'award':'store',helper?'Uy tín':'Mua sắm'],['messages','users','Tin nhắn']].map(([s,i,n])=>`<button data-screen="${s}" class="${navActive(s)?'active':''}">${icon(i)}<span>${n}</span></button>`).join('')}</nav><div class="home-indicator"></div></div><div class="phone-caption">Chạm trực tiếp vào màn hình để dùng thử</div></div><aside class="side-panel"><div class="panel-eyebrow">MỘT ỨNG DỤNG, HAI THẾ HỆ</div><h2>Gần gũi với cô bác.<br>Ý nghĩa với người trẻ.</h2><p class="description">Đổi tài khoản để xem An Vui qua mắt bác Minh, 68 tuổi, hoặc Minh Anh, sinh viên đang giúp các bác.</p><div class="role-toggle" aria-label="Chọn tài khoản"><button data-role="senior" class="${!helper?'active':''}">${icon('user')} Tôi là cô bác</button><button data-role="helper" class="${helper?'active':''}">${icon('heart')} Tôi giúp cô bác</button></div><div class="scenario-list">${(helper?[['questions','01','Trả lời một câu hỏi','Chỉ từng bước, bằng lời dễ hiểu.'],['rewards','02','Tích điểm uy tín','Mỗi lần cô bác làm được, bạn được ghi nhận.'],['requests','03','Nhận buổi hướng dẫn','Gặp cô bác ở gần, chỉ tận tay, có thù lao.']]:[['questions','01','Hỏi điều chưa biết','Có người trẻ trả lời từng bước.'],['friends','02','Kết bạn cùng sở thích','Trồng hoa, đánh cờ, đọc sách…'],['nearby','03','Nhờ người chỉ tận tay','Gặp người hướng dẫn ngay gần nhà.'],['market','04','Mua sắm an tâm','Gian hàng đã duyệt, giá ghi rõ.']]).map(([s,n,t,d])=>`<button class="scenario ${state.screen===s?'active':''}" data-screen="${s}"><span class="scenario-number">${n}</span><span><strong>${t}</strong><small>${d}</small></span></button>`).join('')}</div><div class="family-card"><span class="mini-icon">${icon('gift')}</span><strong>Tặng ba mẹ một nơi có bạn.</strong><p>Cài An Vui cho ba mẹ chỉ mất 5 phút, dù bạn ở gần hay ở xa.</p><button data-action="family">Hướng dẫn cài cho ba mẹ ${icon('arrow')}</button></div></aside></section>`}
function navActive(s){if(s==='questions')return ['questions','question','ask'].includes(state.screen);if(s==='market')return ['market','product','checkout','order-success'].includes(state.screen);if(s==='messages')return ['messages','chat','friends'].includes(state.screen);if(s==='home')return ['home','post','nearby','helper-detail','appointment','requests'].includes(state.screen);return s===state.screen}
function renderScreen(){const screens={home,questions,question,ask,market,product,checkout,orderSuccess,friends:friendsScreen,messages,chat,rewards,profile,identity,post:postScreen,nearby,'helper-detail':helperProfile,appointment,requests:supportRequests};const key=state.screen==='order-success'?'orderSuccess':state.screen;$('#app-content').innerHTML=(key==='home'?installBanner():'')+(screens[key]||home)();document.querySelectorAll('.bottom-nav button').forEach(el=>el.classList.toggle('active',navActive(el.dataset.screen)));document.querySelectorAll('.scenario').forEach(el=>el.classList.toggle('active',el.dataset.screen===state.screen));syncBell();}
function home(){if(state.role==='helper')return `<p class="greeting-date">${todayLabel()}</p><h1 class="greeting">Chào Minh Anh</h1><p class="sub-greeting">Hôm nay có ${state.questions.filter(q=>!q.answers.length).length} cô bác đang chờ bạn giúp.</p><div class="helper-box">${icon('heart')}<div><strong>Bạn đã giúp 86 cô bác</strong><p>Tuần này có 12 người bấm “Đã làm được” sau khi đọc hướng dẫn của bạn.</p></div></div><button class="primary wide" data-screen="questions">${icon('message')} Xem câu hỏi đang chờ</button><button class="secondary wide" data-screen="requests">${icon('pin')} Yêu cầu hướng dẫn gần bạn</button><h2 class="section-label">Tuần này của bạn</h2><div class="community-post"><div class="stat-row"><span>Điểm uy tín</span><strong>${state.points} điểm</strong></div><div class="stat-row"><span>Câu trả lời được cảm ơn</span><strong>12</strong></div><div class="stat-row"><span>Đánh giá trung bình</span><strong>★ 4,9</strong></div><button class="secondary wide" data-screen="rewards">${icon('award')} Xem điểm uy tín</button></div><p class="subtle-note">Tài khoản người hỗ trợ dùng để trả lời và nhắn tin. Mục đăng bài dành cho cô bác.</p>`;const a=state.questions.find(q=>q.id===1)?.answers[0];return `<p class="greeting-date">${todayLabel()}</p><h1 class="greeting">Chào bác Minh</h1><p class="sub-greeting">Chúc bác một ngày nhiều niềm vui.</p>${a?`<button class="update-card" data-question="1">${avatar('MA','orange','Minh Anh')}<span><strong>Minh Anh đã trả lời câu hỏi của bác</strong><small>Gọi video cho cháu trên Zalo thế nào?</small></span>${icon('chevron')}</button>`:''}<div class="home-banner"><img src="assets/community.webp" alt="Ba người bạn lớn tuổi cười vui bên chiếc điện thoại trong vườn"><div class="banner-copy"><span>CÂU LẠC BỘ AN VUI</span><strong>Tuổi vàng,<br>mình cùng kết nối.</strong><button data-screen="friends">Tìm bạn cùng sở thích ${icon('arrow')}</button></div></div><h2 class="section-label">Bác muốn làm gì hôm nay?</h2><div class="quick-grid"><button class="quick-card" data-screen="ask"><span class="quick-icon">${icon('message')}</span>${icon('arrow','quick-arrow')}<strong>Hỏi điều chưa biết</strong><small>Người trẻ trả lời từng bước</small></button><button class="quick-card peach" data-screen="market"><span class="quick-icon">${icon('store')}</span>${icon('arrow','quick-arrow')}<strong>Mua sắm an tâm</strong><small>Gian hàng đã duyệt</small></button></div><button class="nearby-home-card" data-screen="nearby">${icon('pin')}<span><strong>Cần người chỉ tận tay?</strong><small>Hẹn người hướng dẫn gần nhà · 99.000đ/buổi</small></span>${icon('chevron')}</button><h2 class="section-label">Chuyện quanh mình <button data-screen="post">${icon('plus')} Viết bài</button></h2>${state.newPosts.map((body,i)=>communityPost({id:'new-'+i,name:'Bác Minh',initials:'M',detail:'Cầu Giấy · Vừa xong',body})).join('')}${FEED.map(communityPost).join('')}<button class="secondary wide" data-screen="friends">${icon('users')} Tìm thêm bạn trò chuyện</button>`}
function communityPost(p){const liked=state.likes.includes(p.id);return `<article class="community-post">${person(p.name,p.initials,p.detail,p.color||'orange')}<p>${esc(p.body)}</p>${p.img?`<img class="post-picture" src="assets/${p.img}.webp" alt="${esc(p.alt||'')}" loading="lazy">`:''}<div class="post-actions"><button class="${liked?'liked':''}" data-like="${p.id}" aria-pressed="${liked}">${icon('heart')} ${(p.likes||0)+(liked?1:0)} Thích</button><button data-comment="${p.id}">${icon('message')} ${p.comments?p.comments+' bình luận':'Bình luận'}</button></div></article>`}
function questions(){const helper=state.role==='helper';return `<h1 class="screen-title">${helper?'Câu hỏi đang chờ bạn':'Hỏi đáp'}</h1><p class="screen-subtitle">${helper?'Trả lời ngắn gọn, chia từng bước để cô bác làm theo được.':'Điều gì chưa rõ, bác cứ hỏi. Thường chỉ vài phút là có người trả lời.'}</p>${helper?'':`<button class="primary wide" data-screen="ask">${icon('plus')} Đặt câu hỏi mới</button>`}<label class="search-field">${icon('search')}<input id="question-search" aria-label="Tìm câu hỏi" placeholder="Tìm: Zalo, gửi ảnh, OTP…" value="${esc(state.search)}"></label><div class="chips">${['Tất cả','Điện thoại','Ứng dụng','An toàn'].map(t=>`<button class="chip ${state.filter===t?'active':''}" data-question-filter="${t}">${t}</button>`).join('')}</div><div id="question-results">${questionList()}</div>`}
function questionList(){const qs=state.questions.filter(q=>(state.filter==='Tất cả'||q.category===state.filter)&&q.title.toLocaleLowerCase('vi').includes(state.search.toLocaleLowerCase('vi')));return qs.length?qs.map(q=>`<button class="question-card" data-question="${q.id}">${person(q.name,q.initials,`${q.age} tuổi · ${q.time}`)}<h3>${esc(q.title)}</h3><div class="question-meta"><span class="tag ${q.category==='An toàn'?'orange':''}">${esc(q.category)}</span><span>${q.answers.length?q.answers.length+' câu trả lời':'Chưa có trả lời'} ${icon('chevron')}</span></div></button>`).join(''):'<div class="empty">Chưa tìm thấy câu hỏi nào.<br>Bác thử gõ từ khác, hoặc đặt câu hỏi mới nhé.</div>'}
function question(){const q=state.questions.find(q=>q.id===state.questionId)||state.questions[0];const senior=state.role==='senior';return `<button class="back-btn" data-screen="questions">${icon('back')} Hỏi đáp</button>${person(q.name,q.initials,`${q.age} tuổi · ${q.time}`)}<h1 class="screen-title question-title">${esc(q.title)}</h1><p class="question-body">${esc(q.body)}</p>${senior?`<div class="safe-note">${icon('shield')} Đừng đăng mật khẩu, mã OTP hay ảnh giấy tờ trong câu hỏi nhé.</div>`:''}<h2 class="section-label">Câu trả lời (${q.answers.length})</h2>${q.answers.map(a=>{const n=a.likes+(state.helpful.includes(a.id)?1:0);return `<article class="answer-card">${person(a.name,a.initials,a.reviewed?(PEOPLE[a.name]?.tagline||'Người hỗ trợ'):'Đang chờ kiểm duyệt','orange')}<p>${esc(a.body)}</p>${senior?`<button class="answer-helpful ${state.helpful.includes(a.id)?'selected':''}" data-helpful="${a.id}" aria-pressed="${state.helpful.includes(a.id)}">${icon(state.helpful.includes(a.id)?'check':'thumb')} ${state.helpful.includes(a.id)?'Bác đã làm được':'Tôi đã làm được'} · ${n}</button>`:`<span class="tag">${icon('heart')} ${n} người thấy hữu ích</span>`}</article>`}).join('')||(state.typing===q.id?'':'<p class="subtle-note">Chưa có ai trả lời. Các bạn hỗ trợ thường phản hồi trong vòng 30 phút.</p>')}${state.typing===q.id?typingCard():''}${state.role==='helper'?`<form id="answer-form"><label class="field-label" for="answer-body">Câu trả lời của bạn</label><textarea class="form-control" id="answer-body" name="body" required minlength="15" maxlength="2000" placeholder="Ví dụ: Bác mở Cài đặt → chọn Màn hình → kéo thanh Cỡ chữ sang phải…"></textarea><p class="subtle-note">Câu trả lời được kiểm duyệt trước khi hiện công khai. Bạn nhận +10 điểm khi cô bác xác nhận đã làm được.</p><button class="primary wide" type="submit">${icon('send')} Gửi câu trả lời</button></form>`:`<button class="secondary wide" data-chat="minhanh">${icon('message')} Nhắn riêng cho Minh Anh</button>`}`}
function ask(){if(state.role!=='senior')return denied();return `<button class="back-btn" data-screen="questions">${icon('back')} Hỏi đáp</button><h1 class="screen-title">Bác muốn hỏi gì?</h1><p class="screen-subtitle">Bác kể càng cụ thể, các cháu càng dễ chỉ.</p><form id="question-form"><label class="field-label" for="q-title">Bác cần giúp việc gì?</label><input id="q-title" name="title" class="form-control" required minlength="8" maxlength="150" placeholder="Ví dụ: Cách gọi video cho cháu trên Zalo"><label class="field-label" for="q-category">Chủ đề</label><select id="q-category" class="form-control" name="category"><option>Điện thoại</option><option>Ứng dụng</option><option>An toàn</option></select><label class="field-label" for="q-body">Bác kể thêm một chút</label><textarea id="q-body" name="body" class="form-control" required minlength="10" maxlength="2000" placeholder="Bác dùng máy gì, đã thử bấm những đâu, đang vướng ở bước nào?"></textarea><button type="button" class="secondary wide" data-action="dictate">${icon('mic')} Nói thay vì gõ</button><div class="safe-note">${icon('shield')} Câu hỏi sẽ hiện công khai trong cộng đồng. Bác đừng ghi số điện thoại, mật khẩu hay mã OTP nhé.</div><button type="submit" class="primary wide">${icon('send')} Gửi câu hỏi</button></form>`}
function denied(){return `<div class="empty">Mục này dành cho tài khoản cô bác.<br>Bạn có thể giúp các bác ở mục Hỏi đáp.</div><button class="primary wide" data-screen="questions">Xem câu hỏi đang chờ</button>`}
function postScreen(){if(state.role!=='senior')return denied();return `<button class="back-btn" data-screen="home">${icon('back')} Trang chủ</button><h1 class="screen-title">Viết bài mới</h1><p class="screen-subtitle">Một khoảnh khắc vui, một chậu hoa đẹp hay một lời rủ đi dạo.</p><form id="post-form"><label class="field-label" for="post-body">Bác muốn kể điều gì?</label><textarea class="form-control" id="post-body" name="body" required minlength="5" maxlength="1500" placeholder="Hôm nay tôi…"></textarea><p class="subtle-note">Bài viết hiện với bạn bè và cô bác cùng khu vực. Bác đừng đăng số điện thoại hay địa chỉ nhà nhé.</p><button class="primary wide" type="submit">${icon('send')} Đăng bài</button></form>`}
function market(){if(state.role==='helper')return rewards();return `<h1 class="screen-title">Mua sắm an tâm</h1><p class="screen-subtitle">Đồ dùng hằng ngày và quà nhỏ cho mình, cho người thân.</p><div class="safe-note positive">${icon('shield')} Mọi gian hàng đều được An Vui kiểm tra trước khi mở bán. Thanh toán khi nhận hàng.</div><div class="chips">${['Tất cả','Thư giãn','Đồ dùng','Sở thích'].map(t=>`<button class="chip ${state.filter===t?'active':''}" data-market-filter="${t}">${t}</button>`).join('')}</div><div class="product-grid">${products.filter(p=>state.filter==='Tất cả'||p.category===state.filter).map(p=>`<button class="product-card" data-product="${p.id}"><img class="product-photo" src="assets/${p.img}.webp" alt="${esc(p.name)}" loading="lazy"><div class="product-info">${p.sponsored?'<span class="sponsor-tag">Tài trợ</span>':''}<h3>${p.name}</h3><span class="price">${vnd(p.price)}</span><small>${p.shop} · ★ ${p.rating} (${p.reviews})</small></div></button>`).join('')}</div>`}
function product(){if(state.role!=='senior')return denied();const p=products.find(p=>p.id===state.productId)||products[0];return `<button class="back-btn" data-screen="market">${icon('back')} Mua sắm</button><article class="product-detail"><img class="product-hero" src="assets/${p.img}.webp" alt="${esc(p.name)}">${p.sponsored?'<span class="sponsor-tag">Tài trợ</span>':''}<h2>${p.name}</h2><div class="seller-line">${icon('shield')} ${p.shop} · ★ ${p.rating} (${p.reviews} đánh giá)</div><div class="product-price">${vnd(p.price)}</div><p>${p.desc}</p><div class="stat-row"><span>Giao hàng</span><strong>1–2 ngày · 20.000đ</strong></div><div class="stat-row"><span>Thanh toán</span><strong>Khi nhận hàng</strong></div><div class="product-actions"><button class="primary wide" data-screen="checkout">${icon('bag')} Đặt mua</button><button class="secondary wide" data-action="family-order">${icon('gift')} Nhờ con cháu mua giúp</button></div></article>`}
function checkout(){if(state.role!=='senior')return denied();const p=products.find(p=>p.id===state.productId)||products[0];return `<button class="back-btn" data-screen="product">${icon('back')} Sản phẩm</button><h1 class="screen-title">Xác nhận đơn hàng</h1><p class="screen-subtitle">Bác xem lại thông tin trước khi đặt nhé.</p><div class="community-post"><h2 class="card-title">${p.name}</h2><div class="stat-row"><span>Số lượng</span><strong>1</strong></div><div class="stat-row"><span>Giá sản phẩm</span><strong>${vnd(p.price)}</strong></div><div class="stat-row"><span>Phí giao hàng</span><strong>20.000đ</strong></div><div class="stat-row"><span>Tổng cộng</span><strong>${vnd(p.price+20000)}</strong></div></div><div class="notice"><strong>Giao đến:</strong> Bác Minh · 0912 *** 468<br>Số 12 ngõ 75 Trần Quốc Hoàn, Cầu Giấy, Hà Nội<br><strong>Thanh toán:</strong> Tiền mặt khi nhận hàng</div><button class="primary wide" data-screen="order-success">${icon('check')} Đặt hàng</button>`}
function orderSuccess(){if(state.role!=='senior')return denied();const p=products.find(p=>p.id===state.productId)||products[0];return `<div class="success-block"><div class="success-icon">${icon('check')}</div><h1 class="screen-title">Đặt hàng thành công!</h1><p>Đơn <strong>#AV${p.code}</strong> đã được gửi tới ${p.shop}. Cửa hàng sẽ gọi cho bác để xác nhận trước khi giao, dự kiến trong 1–2 ngày.</p><button class="primary wide" data-screen="market">${icon('store')} Tiếp tục mua sắm</button><button class="secondary wide" data-screen="home">Về trang chủ</button></div>`}
function friendsScreen(){if(state.role==='helper')return messages();return `<button class="back-btn" data-screen="home">${icon('back')} Trang chủ</button><h1 class="screen-title">Gợi ý kết bạn</h1><p class="screen-subtitle">Cô bác ở gần, có cùng sở thích với bác.</p>${friends.map(f=>`<article class="friend-card">${person(f.name,f.initials,`${f.age} tuổi · ${f.place}`,f.color)}<p>${f.bio}</p><div class="interest-tags">${f.interests.map(t=>`<span class="tag">${t}</span>`).join('')}</div><button class="secondary" ${state.friends.includes(f.id)?`data-chat="${f.id}"`:`data-friend="${f.id}"`}>${icon(state.friends.includes(f.id)?'message':'user-plus')} ${state.friends.includes(f.id)?'Nhắn tin':'Kết bạn'}</button></article>`).join('')}<p class="subtle-note">Mọi người chỉ thấy quận nơi bác sống, không thấy địa chỉ cụ thể.</p>`}
function messages(){return `<h1 class="screen-title">Tin nhắn</h1><p class="screen-subtitle">Một lời hỏi thăm, thêm chút ấm lòng.</p>${state.role==='senior'?'<button class="secondary wide" data-screen="friends">'+icon('users')+' Tìm bạn mới</button>':''}<div class="conversation-list">${Object.keys(state.messages).map(id=>{const f=friends.find(f=>f.id===id)||{name:'Minh Anh',initials:'MA',color:'orange'};const asHelper=state.role==='helper'&&id==='minhanh';const name=asHelper?'Bác Minh':f.name;const ms=state.messages[id];const last=ms[ms.length-1];const text=last?(last.me?'Bạn: ':'')+last.text:'Gửi lời chào đầu tiên nhé!';return `<button class="conversation" data-chat="${id}">${asHelper?avatar('M','','Bác Minh'):avatar(f.initials,f.color,f.name)}<span class="person-info"><strong>${name}</strong><p>${esc(text)}</p></span><time>${CHAT_TIMES[id]||'Vừa xong'}</time></button>`}).join('')}</div><div class="safe-note">${icon('shield')} Nếu ai đó làm bác khó chịu, hỏi tiền hay hỏi mã OTP, bác bấm “Báo cáo” trong cuộc trò chuyện nhé.</div>`}
function chat(){const helper=state.role==='helper';const f=friends.find(f=>f.id===state.chatId)||{name:helper?'Bác Minh':'Minh Anh',initials:helper?'M':'MA',color:helper?'':'orange'};const detail=friends.some(x=>x.id===state.chatId)?`Bạn bè · ${f.place}`:helper?'68 tuổi · Cầu Giấy, Hà Nội':'Người hỗ trợ · Thường trả lời trong vài phút';return `<button class="back-btn" data-screen="messages">${icon('back')} Tin nhắn</button>${person(f.name,f.initials,detail,f.color)}<div class="chat-bubbles">${(state.messages[state.chatId]||[]).map(m=>`<div class="bubble ${m.me?'me':''}">${esc(m.text)}</div>`).join('')}</div><form id="chat-form" class="chat-form"><input class="form-control" name="message" id="chat-input" aria-label="Nội dung tin nhắn" placeholder="Nhập tin nhắn…" required maxlength="1500" autocomplete="off"><button class="primary" type="submit" aria-label="Gửi tin nhắn">${icon('send')}</button></form><button class="ghost-button danger" data-action="report">${icon('flag')} Báo cáo hoặc chặn</button>`}
function rewards(){const available=Math.min(100,state.points/200*100);return `<h1 class="screen-title">Điểm uy tín</h1><p class="screen-subtitle">Ghi nhận mỗi lần bạn giúp cô bác làm được việc.</p><div class="helper-box"><span class="points">${state.points}</span><div><strong>điểm uy tín</strong><p>Hạng hiện tại: Người hỗ trợ tận tâm</p></div></div><div class="community-post"><span class="tag">${icon('gift')} Ưu đãi cho gian hàng của bạn</span><h2 class="card-title">200 điểm đổi 7 ngày hiển thị nổi bật</h2><div class="progress-track"><div class="progress-fill" style="width:${available}%"></div></div><p class="subtle-note">${state.points>=200?'Bạn đã đủ điểm đổi ưu đãi.':`Còn ${200-state.points} điểm nữa là đổi được.`}</p><button class="${state.points>=200?'primary':'secondary'} wide" data-action="redeem" ${state.redeemed?'disabled':''}>${state.redeemed?'Đã đổi ưu đãi':'Đổi ưu đãi'}</button><p class="subtle-note">Áp dụng cho gian hàng đã được duyệt. Vị trí nổi bật luôn gắn nhãn “Tài trợ”. Điểm không đổi được thành tiền.</p></div><h2 class="section-label">Cách tính điểm</h2><div class="stat-row"><span>Cô bác xác nhận đã làm được theo hướng dẫn của bạn</span><strong>+10</strong></div><div class="stat-row"><span>Người khác thấy câu trả lời của bạn hữu ích</span><strong>+2</strong></div><p class="subtle-note">Điểm được đối soát sau 7 ngày. Các tài khoản bấm qua lại cho nhau để lấy điểm sẽ bị trừ điểm.</p><button class="primary wide" data-screen="questions">${icon('message')} Tiếp tục giúp cô bác</button>`}
function profile(){const helper=state.role==='helper';return `<div class="profile-hero">${avatar(helper?'MA':'M',helper?'orange':'',helper?'Minh Anh':'Bác Minh')}<div><h2>${helper?'Minh Anh':'Bác Minh'}</h2><p>${helper?'22 tuổi · Người hỗ trợ · ★ 4,9':'68 tuổi · Cầu Giấy, Hà Nội'}</p></div></div><span class="tag">${icon('badge')} Đã xác thực danh tính</span><h2 class="section-label">Cài đặt</h2><button class="setting-row" data-action="font"><span>${icon('textsize')} Cỡ chữ</span><small>${['Lớn','Rất lớn','Lớn nhất'][state.font]}</small></button><button class="setting-row" data-action="read"><span>${icon('volume')} Đọc to nội dung màn hình</span>${icon('chevron')}</button><button class="setting-row" data-screen="${helper?'requests':'nearby'}"><span>${icon('pin')} ${helper?'Yêu cầu hướng dẫn':'Nhờ người chỉ tận tay'}</span>${icon('chevron')}</button><button class="setting-row" data-screen="identity"><span>${icon('card')} Xác thực tài khoản</span><small>Đã xác thực</small></button>${helper?`<button class="setting-row" data-screen="rewards"><span>${icon('award')} Điểm uy tín</span><small>${state.points} điểm</small></button>`:''}<button class="setting-row" data-action="family"><span>${icon('gift')} Kết nối với gia đình</span>${icon('chevron')}</button><button class="setting-row" data-action="install"><span>${icon('download')} Thêm An Vui ra màn hình chính</span>${icon('chevron')}</button><h2 class="section-label">Chế độ trình diễn</h2><p class="subtle-note">Dùng khi giới thiệu An Vui: đổi tài khoản để xem cả hai phía.</p><div class="role-toggle"><button data-role="senior" class="${!helper?'active':''}">Bác Minh</button><button data-role="helper" class="${helper?'active':''}">Minh Anh</button></div><button class="setting-row solo" data-action="reset-ask"><span>${icon('reset')} Bắt đầu lại từ đầu</span>${icon('chevron')}</button><div class="made-by"><img src="assets/zentech-mark.webp" alt="" width="28" height="28"><span>An Vui · phát triển bởi <b>Zentech</b><small>Đơn giản là sức mạnh</small></span></div>`}
function identity(){const helper=state.role==='helper';return `<button class="back-btn" data-screen="profile">${icon('back')} Tài khoản</button><h1 class="screen-title">Xác thực tài khoản</h1><p class="screen-subtitle">Giúp cộng đồng biết bạn là người thật, đúng độ tuổi.</p><div class="verify-status">${icon('badge')}<div><strong>Đã xác thực danh tính</strong><p>Qua căn cước gắn chip · ${helper?'12/08/2026':'03/09/2026'}</p></div></div><h2 class="section-label">Vì sao cần xác thực?</h2><div class="community-post"><div class="stat-row"><span>Cô bác, từ 60 tuổi</span><strong class="wrap-value">Hỏi, đăng bài, mua sắm</strong></div><div class="stat-row"><span>Người hỗ trợ, 18–59 tuổi</span><strong class="wrap-value">Trả lời, hướng dẫn</strong></div><p class="subtle-note">An Vui chỉ lưu kết quả xác thực và nhóm tuổi, không lưu ảnh giấy tờ của bạn.</p></div><h2 class="section-label">Chế độ trình diễn</h2><button class="identity-choice" data-verify="senior">${icon('user')}<span><strong>Xem với tài khoản cô bác</strong><small>Bác Minh, 68 tuổi</small></span></button><button class="identity-choice" data-verify="helper">${icon('heart')}<span><strong>Xem với tài khoản người hỗ trợ</strong><small>Minh Anh, 22 tuổi</small></span></button>`}
function business(){return `<section class="strategy-page"><div class="strategy-topline"><div class="view-heading"><div class="eyebrow">GIÁ TRỊ THẬT, DOANH THU BỀN VỮNG</div><h1>Cộng đồng là nền tảng.<br>Niềm tin tạo ra giá trị.</h1><p>Cô bác dùng miễn phí những việc thiết yếu. Đối tác và gia đình trả tiền cho dịch vụ có giá trị rõ ràng.</p></div><span class="assumption-pill">Các mức phí là giả định cần thử nghiệm</span></div><div class="revenue-grid"><article class="revenue-card">${icon('store')}<h2>Phí trên đơn thành công</h2><p>Gian hàng trả phí khi giao dịch hoàn tất, đã trừ đơn hủy và hoàn trả.</p><div class="amount">8% <small>/ giá trị sản phẩm</small></div><small>Ưu tiên đồ dùng, sở thích và quà tặng. Bắt đầu với đối tác chọn lọc.</small></article><article class="revenue-card">${icon('wallet')}<h2>Gói gian hàng đối tác</h2><p>Công cụ quản lý đơn, nội dung sản phẩm và báo cáo cho cửa hàng đã duyệt.</p><div class="amount">199.000đ <small>/ gian hàng / tháng</small></div><small>Hiển thị tài trợ có nhãn riêng. Điểm đóng góp đổi ưu đãi, không thay thế duyệt hàng.</small></article><article class="revenue-card">${icon('gift')}<h2>Gói Gia đình An Tâm</h2><p>Lịch hướng dẫn công nghệ định kỳ cho ba mẹ, kèm hỗ trợ mua quà gửi về nhà.</p><div class="amount">49.000đ <small>/ gia đình / tháng</small></div><small>Hỏi đáp cộng đồng vẫn miễn phí. Không cho con cháu đọc tin nhắn riêng của ba mẹ.</small></article></div>${serviceRevenue()}<div class="flow"><span>Cô bác có người giúp</span>${icon('arrow')}<span>Cộng đồng có uy tín</span>${icon('arrow')}<span>Mua sắm có niềm tin</span>${icon('arrow')}<span>Đối tác trả phí</span></div><div class="calc-area"><div class="calc-inputs"><h2>Mô phỏng doanh thu một tháng</h2><p>Kéo từng thanh để thay đổi giả định. Con số dùng để thảo luận, chưa phải dự báo.</p>${range('orders','Đơn hoàn tất / tháng',150,0,1000,10)}${range('basket','Giá trị sản phẩm / đơn',300000,100000,700000,50000)}${range('commission','Phí giao dịch',8,0,15,1)}${range('shops','Gian hàng trả phí',10,0,100,1)}${range('families','Gia đình trả phí',20,0,300,5)}${range('costs','Chi phí cố định / tháng',8000000,0,30000000,500000)}<p class="subtle-note">Chi phí biến đổi giả định: 5.000đ/đơn. Chi phí cố định là tổng nhóm tự ước tính cho vận hành, xác thực, kiểm duyệt và tiếp thị. Không gồm thuế hay ưu đãi.</p></div><div class="calc-results" aria-live="polite" id="calc-results"></div></div><div class="strategy-columns"><article class="strategy-section"><h2>Giúp đỡ có chất lượng</h2><ol><li><strong>Người hỏi xác nhận “đã làm được”.</strong> Một câu trả lời đủ điều kiện được +10 điểm một lần.</li><li><strong>AI hỗ trợ sàng lọc.</strong> Câu trả lời công nghệ được đối chiếu hướng dẫn; trường hợp không chắc phải chuyển người kiểm duyệt. Lượt thích không chứng minh câu trả lời đúng.</li><li><strong>Chống trao đổi tương tác.</strong> Giới hạn điểm từ lượt thích, kiểm tra tài khoản liên quan và có thời gian đối soát trước khi đổi ưu đãi.</li><li><strong>Uy tín và hàng hóa được xét riêng.</strong> Người trẻ muốn bán hàng cần đăng ký hồ sơ kinh doanh riêng. Điểm không tự tạo quyền ghim bất kỳ sản phẩm nào.</li></ol></article><article class="strategy-section"><h2>Lý do để tin và quay lại</h2><ul><li><strong>Chữ lớn, thao tác rõ:</strong> nhãn tiếng Việt, vùng bấm rộng, phóng chữ, hỏi bằng giọng nói nếu thiết bị hỗ trợ.</li><li><strong>Con cháu giúp khởi đầu:</strong> cài ra màn hình chính, chọn cỡ chữ, thử cuộc gọi và kết nối một người bạn.</li><li><strong>Ba mẹ giữ quyền riêng tư:</strong> chỉ chia sẻ yêu cầu hỗ trợ hoặc đơn hàng khi chủ động đồng ý.</li><li><strong>Chợ chọn lọc từ đầu:</strong> chưa mở bán tự do hay quảng cáo sản phẩm có tuyên bố chữa bệnh. Quy trình khiếu nại cần có người phụ trách.</li></ul></article></div><div class="sources">Cơ sở thiết kế: <a href="https://www.w3.org/WAI/older-users/developing/" target="_blank" rel="noopener">W3C — Thiết kế web cho người lớn tuổi ↗</a><a href="https://vietnam.unfpa.org/en/topics/ageing-0" target="_blank" rel="noopener">UNFPA Việt Nam — Già hóa dân số ↗</a><br>Mọi mức phí và con số trên trang này là giả định để thảo luận, sẽ được kiểm chứng trong giai đoạn thử nghiệm. Tài khoản và hoạt động trong ứng dụng là dữ liệu minh họa.</div></section>`}
function range(id,label,value,min,max,step){return `<div class="range-field"><label class="calc-label" for="calc-${id}"><span>${label}</span><strong id="label-${id}"></strong></label><input type="range" id="calc-${id}" name="${id}" min="${min}" max="${max}" step="${step}" value="${value}"></div>`}
function calculate({orders,basket,commission,shops,families,costs}){const gross=orders*basket,transaction=gross*commission/100,store=shops*199000,family=families*49000,revenue=transaction+store+family,variable=orders*5000;return{gross,transaction,store,family,revenue,variable,totalCosts:costs+variable,profit:revenue-costs-variable}}
function updateCalculator(){const values={};for(const id of ['orders','basket','commission','shops','families','costs']){values[id]=Number($('#calc-'+id)?.value||0);const el=$('#label-'+id);if(el)el.textContent=['basket','costs'].includes(id)?vnd(values[id]):id==='commission'?values[id]+'%':values[id].toLocaleString('vi-VN')}const c=calculate(values);$('#calc-results').innerHTML=`<div class="eyebrow">DOANH THU ƯỚC TÍNH / THÁNG</div><div class="total">${vnd(c.revenue)}</div><div class="total-label">Tổng doanh thu từ ba nguồn</div><div class="stat-row"><span>Phí giao dịch</span><strong>${vnd(c.transaction)}</strong></div><div class="stat-row"><span>Gói gian hàng</span><strong>${vnd(c.store)}</strong></div><div class="stat-row"><span>Gói gia đình</span><strong>${vnd(c.family)}</strong></div><div class="stat-row"><span>Tổng chi phí giả định</span><strong>${vnd(c.totalCosts)}</strong></div><div class="stat-row result-highlight"><span>${c.profit>=0?'Còn lại trước thuế':'Thiếu để hòa vốn'}</span><strong>${vnd(Math.abs(c.profit))}</strong></div><p class="result-note">Tổng giá trị sản phẩm bán qua chợ (GMV): ${vnd(c.gross)}. GMV không phải doanh thu của An Vui. ${c.profit<0?'Kịch bản hiện tại chưa hòa vốn; cần kiểm chứng nhu cầu trả phí và tối ưu chi phí.':'Kết quả dương phụ thuộc hoàn toàn vào giả định trên; cần thử nghiệm thực tế.'}</p>`}
function launch(){return `<section class="strategy-page"><div class="strategy-topline"><div class="view-heading"><div class="eyebrow">BẮT ĐẦU NHỎ, HỌC TỪ NGƯỜI DÙNG</div><h1>Con cháu giúp cài.<br>Niềm vui giữ ba mẹ ở lại.</h1><p>Không chỉ đo lượt tải. Hãy đo xem cô bác có tự làm được việc mình cần và có muốn quay lại không.</p></div><button class="secondary print-button" data-action="print">${icon('printer')} In kế hoạch</button></div>${qrCard()}<div class="quote">“Cài cho ba mẹ một nơi có bạn, có người chỉ cách dùng điện thoại và có thêm niềm vui mỗi ngày.”</div><div class="launch-grid"><article class="launch-card"><span class="week">TUẦN 1 · CÙNG HIỂU</span><h2>Gặp đúng người,<br>hỏi đúng khó khăn.</h2><p>Chọn một câu lạc bộ người cao tuổi ở cùng địa bàn để bắt đầu.</p><ul><li>Phỏng vấn 10 cô bác 60–75 tuổi đã có điện thoại thông minh và 5 người con.</li><li>Quan sát thao tác, không chỉ hỏi “bác có thích không”.</li><li>Tuyển 10 người trẻ hỗ trợ trong các khung giờ rõ ràng.</li></ul></article><article class="launch-card"><span class="week">TUẦN 2–3 · CÙNG THỬ</span><h2>Cài một lần,<br>làm được việc ngay.</h2><p>Thử với 30 cô bác, người thân của họ và 3–5 gian hàng chọn lọc.</p><ul><li>Tiếp cận qua câu lạc bộ, tổ dân phố và hoạt động tình nguyện.</li><li>Gửi con cháu video cài giúp dài 30 giây; cho dùng thử trên web trước.</li><li>Buổi đầu hoàn thành 1 câu hỏi và 1 kết nối bạn bè.</li></ul></article><article class="launch-card"><span class="week">TUẦN 4 · CÙNG ĐO</span><h2>Có quay lại?<br>Có sẵn lòng trả phí?</h2><p>Phỏng vấn lại người dùng và đối tác sau khi đã có trải nghiệm.</p><ul><li>Kiểm tra quay lại sau 7 ngày và tỷ lệ câu hỏi giải quyết được.</li><li>Mời đối tác thử một mức phí cụ thể sau các đơn đầu tiên.</li><li>Thử gói hỗ trợ gia đình có phạm vi rõ; ghi nhận cả lý do từ chối.</li></ul></article></div><div class="strategy-columns"><article class="strategy-section"><h2>Hai người dùng, hai lý do bắt đầu</h2><p><strong>Với cô bác:</strong> “Có người kiên nhẫn chỉ tôi cách dùng điện thoại, có bạn cùng sở thích.” Lợi ích phải xuất hiện ngay trong buổi đầu.</p><p><strong>Với con cháu:</strong> “Ba mẹ có nơi hỏi khi mình bận và bớt ngại công nghệ.” Đưa ra bộ cài giúp đơn giản, tôn trọng sự đồng ý của ba mẹ.</p><p><strong>Khuyến khích giới thiệu:</strong> tặng buổi hướng dẫn công nghệ cho gia đình khi một cô bác mới hoàn thành trải nghiệm đầu tiên; không thưởng theo lượt cài đơn thuần.</p></article><article class="strategy-section"><h2>Buổi cài giúp khoảng 5 phút</h2><ol><li><strong>Mở link, dùng thử trước.</strong> Chưa yêu cầu gửi giấy tờ để xem nội dung giới thiệu.</li><li><strong>Thêm ra màn hình chính.</strong> Có biểu tượng An Vui để mở như ứng dụng web.</li><li><strong>Chọn chữ và sở thích.</strong> Để ba mẹ tự thử nút hỏi, gửi tin và quay về trang chủ.</li><li><strong>Xác thực trước khi tương tác.</strong> Kết nối nhà cung cấp eKYC ở giai đoạn sau; bản trình diễn dùng tài khoản đã xác thực sẵn.</li></ol></article></div><article class="strategy-section"><h2>Điều cần chứng minh sau thử nghiệm</h2><p>Các ngưỡng dưới đây là mục tiêu đặt trước để đánh giá, chưa phải số liệu thực tế.</p><table class="metric-table"><thead><tr><th>Giả thuyết</th><th>Cách kiểm tra</th><th>Mục tiêu thử</th></tr></thead><tbody><tr><td>Cô bác tự dùng được</td><td>Tự đăng câu hỏi và mở tin nhắn sau hướng dẫn</td><td>Ít nhất 8/10 người</td></tr><tr><td>Có ích nên quay lại</td><td>Cô bác có hoạt động trong ngày thứ 7</td><td>Ít nhất 40%</td></tr><tr><td>Hỗ trợ giải quyết được việc</td><td>Người hỏi xác nhận đã làm được</td><td>Ít nhất 60% câu hỏi</td></tr><tr><td>Đối tác sẵn lòng trả tiền</td><td>Chấp nhận mức phí cụ thể sau trải nghiệm</td><td>Ít nhất 3/5 đối tác thử</td></tr><tr><td>Con cháu có nhu cầu trả phí</td><td>Đăng ký trả phí cho gói hỗ trợ có phạm vi rõ</td><td>Thử với 10 gia đình</td></tr></tbody></table></article><div class="pitch-script"><h2>Kịch bản thuyết trình 3 phút</h2><p><strong>0:00–0:30 · Vấn đề:</strong> bác Minh muốn gọi cho cháu nhưng ngại hỏi đi hỏi lại. Con bận, bác cần người hướng dẫn dễ hiểu.<br><strong>0:30–1:30 · Demo:</strong> đặt câu hỏi → đổi vai người trẻ → gửi câu trả lời → cô bác xác nhận → tìm bạn và nhắn tin.<br><strong>1:30–2:15 · Doanh thu:</strong> mở Mua sắm, thử nhờ con mua giúp; chuyển bảng doanh thu, thay đổi giả định và chỉ rõ chi phí.<br><strong>2:15–3:00 · Kiểm chứng:</strong> trình bày kế hoạch thử với 30 cô bác, tiêu chí tự dùng được và ý định trả phí thực tế.</p><div class="pitch-actions"><button class="primary" data-action="start-pitch">Bắt đầu trình diễn ${icon('arrow')}</button><button class="secondary" data-view="business">Xem bài toán doanh thu</button></div></div><section class="team-section"><img src="assets/zentech-logo.webp" alt="Logo nhóm Zentech" width="360" height="369"><div><div class="eyebrow team-eyebrow">NHÓM THỰC HIỆN</div><h2>Zentech<br>Đơn giản là sức mạnh.</h2><p><strong>Zen</strong> là tối giản, <strong>Tech</strong> là công nghệ. Zentech hướng đến những sản phẩm công nghệ đơn giản nhưng hiệu quả.</p><p>An Vui là cách nhóm đưa tinh thần ấy đến với cô bác: chữ lớn, ít nút, mỗi màn hình một việc chính và luôn có người chỉ tận tay.</p></div></section></section>`}
function openModal(title,content){$('#modal-content').innerHTML=`<div class="modal-top"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Đóng">${icon('close')}</button></div>${content}`;if(!$('#modal').open)$('#modal').showModal()}
function family(step=0){if(step===1){openModal('Cài An Vui cho ba mẹ',`<div class="family-progress"><span>1. Mở An Vui</span>${icon('arrow')}<span>2. Chọn cỡ chữ</span>${icon('arrow')}<span>3. Hỏi thử</span></div><p class="modal-text">Ngồi cùng ba mẹ, mở An Vui trên điện thoại của ba mẹ. Chọn cỡ chữ vừa mắt rồi cùng hỏi một câu quen thuộc, như “Gọi video cho cháu thế nào?”.</p><label class="modal-label" for="family-font">Cỡ chữ cho ba mẹ</label><select class="form-control" id="family-font"><option value="0" ${state.font===0?'selected':''}>Lớn</option><option value="1" ${state.font===1?'selected':''}>Rất lớn</option><option value="2" ${state.font===2?'selected':''}>Lớn nhất</option></select><div class="modal-actions"><button class="secondary" data-action="install">${icon('download')} Thêm ra màn hình</button><button class="primary" data-action="family-finish">Bắt đầu cùng ba mẹ ${icon('arrow')}</button></div><p class="subtle-note">An Vui chạy ngay trên trình duyệt, không cần tải từ kho ứng dụng.</p>`);return}openModal('Cùng ba mẹ dùng An Vui',`<p class="modal-text">Bạn giúp ba mẹ bắt đầu, phần còn lại để ba mẹ tự khám phá.</p><div class="modal-feature">${icon('phone')}<div><strong>Cài xong trong 5 phút</strong><p>Thêm biểu tượng ra màn hình, chọn cỡ chữ và cùng ba mẹ hỏi câu đầu tiên.</p></div></div><div class="modal-feature">${icon('shield')}<div><strong>Ba mẹ giữ quyền riêng tư</strong><p>Bạn chỉ nhận được yêu cầu khi ba mẹ chủ động gửi. Tin nhắn riêng của ba mẹ vẫn là của ba mẹ.</p></div></div><div class="modal-feature">${icon('gift')}<div><strong>Gói Gia đình An Tâm · 49.000đ/tháng</strong><p>Lịch hướng dẫn công nghệ định kỳ cho ba mẹ và hỗ trợ mua quà gửi về nhà.</p></div></div><div class="modal-actions"><button class="primary" data-action="family-next">Bắt đầu cài cho ba mẹ ${icon('arrow')}</button></div>`)}
let onboardingIndex=0;
function onboarding(){const steps=[['message','Điều gì chưa biết, cứ hỏi','Gõ hoặc nói câu hỏi của bác. Các bạn trẻ sẽ trả lời từng bước, dễ làm theo.'],['users','Thêm bạn, thêm vui','Tìm cô bác cùng sở thích ở gần, kết bạn và trò chuyện mỗi ngày.'],['store','Mua sắm có người đồng hành','Giá ghi rõ, gian hàng đã duyệt, và bác luôn có thể nhờ con cháu mua giúp.']];const [i,t,d]=steps[onboardingIndex];openModal('Chào mừng bác đến với An Vui',`<div class="onboarding-step"><div class="large-icon">${icon(i)}</div><h3>${t}</h3><p>${d}</p><div class="step-dots">${steps.map((_,j)=>`<span class="${j===onboardingIndex?'active':''}"></span>`).join('')}</div></div><div class="modal-actions">${onboardingIndex?'<button class="secondary" data-action="onboarding-back">Quay lại</button>':''}<button class="primary" data-action="onboarding-next">${onboardingIndex===2?'Bắt đầu thôi':'Tiếp tục'} ${icon('arrow')}</button></div>`)}
function install(){if(installPrompt){installPrompt.prompt();installPrompt.userChoice.then(()=>installPrompt=null);return}openModal('Thêm An Vui ra màn hình chính',`<p class="modal-text">Mở An Vui chỉ bằng một chạm, như mọi ứng dụng khác. Không cần tải từ App Store hay Google Play.</p><div class="modal-feature">${icon('phone')}<div><strong>iPhone / iPad</strong><ol class="install-steps"><li>Mở An Vui bằng <b>Safari</b>.</li><li>Bấm nút <b>Chia sẻ</b> (ô vuông có mũi tên lên) ở thanh dưới.</li><li>Kéo xuống, chọn <b>Thêm vào MH chính</b>.</li><li>Bấm <b>Thêm</b>. Biểu tượng An Vui sẽ nằm trên màn hình.</li></ol></div></div><div class="modal-feature">${icon('phone')}<div><strong>Android</strong><p>Trong Chrome, bấm nút ⋮ ở góc trên, chọn <b>Thêm vào màn hình chính</b> hoặc <b>Cài đặt ứng dụng</b>.</p></div></div><div class="modal-actions"><button class="primary" data-action="close-modal">Đã hiểu</button></div>`)}
function dictate(){const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SpeechRecognition){toast('Thiết bị chưa hỗ trợ nhập giọng nói ở đây. Bác có thể bấm biểu tượng mic trên bàn phím điện thoại.');return}try{recognition=new SpeechRecognition();recognition.lang='vi-VN';recognition.interimResults=false;recognition.onresult=e=>{const el=$('#q-body');if(el)el.value+=(el.value?' ':'')+e.results[0][0].transcript;toast('Đã điền lời bác nói vào phần kể thêm. Bác kiểm tra rồi gửi nhé.');};recognition.onerror=()=>toast('Chưa nghe được giọng nói. Bác kiểm tra quyền micro hoặc dùng bàn phím nhé.');recognition.start();toast('Đang nghe… Bác nói nội dung cần hỏi nhé.')}catch{toast('Bác thử lại hoặc dùng bàn phím nhé.')}}
const actions={
 ...featureActions,
 'about-zentech'(){openModal('Về nhóm Zentech',`<div class="about-zen"><img src="assets/zentech-logo.webp" alt="Logo Zentech" width="360" height="369"><p class="about-zen-slogan">Đơn giản là sức mạnh.</p><p class="modal-text"><strong>Zen</strong> là tối giản, <strong>Tech</strong> là công nghệ. Zentech làm những sản phẩm công nghệ đơn giản nhưng hiệu quả. An Vui là sản phẩm của nhóm dành cho người cao tuổi.</p></div><div class="modal-actions"><button class="primary" data-action="close-modal">Đóng</button></div>`)},
 'go-home'(){state.view='experience';screenTo('home');window.scrollTo({top:0,behavior:'smooth'})},
 'reset-ask'(){openModal('Bắt đầu lại từ đầu?',`<p class="modal-text">Câu hỏi, tin nhắn, lịch hẹn và điểm vừa thử trong buổi trình diễn sẽ được xóa để bắt đầu lại.</p><div class="modal-actions"><button class="secondary" data-action="close-modal">Giữ nguyên</button><button class="primary" data-action="reset">Bắt đầu lại</button></div>`)},
 'install-dismiss'(){try{localStorage.setItem('anvui-install-hint','hidden')}catch{}renderScreen()},
 compact(){const pos=$('#app-scroll')?.scrollTop||0;state.compact=!state.compact;persist();render();$('#app-scroll')?.scrollTo(0,pos);toast(state.compact?'Đã ẩn ghi chú demo':'Đã hiện lại ghi chú demo')},
 reset(){cancelLive();livePosition=null;recognition?.abort();window.speechSynthesis?.cancel();state=defaultState();persist();$('#modal').close();try{history.replaceState({view:state.view,screen:state.screen},'')}catch{}render();toast('Đã bắt đầu lại từ đầu')},
 onboarding(){onboardingIndex=0;onboarding()},'onboarding-next'(){if(onboardingIndex<2){onboardingIndex++;onboarding()}else{$('#modal').close();screenTo('ask')}},'onboarding-back'(){onboardingIndex--;onboarding()},
 'close-modal'(){$('#modal').close()},font(){const pos=$('#app-scroll')?.scrollTop||0;state.font=(state.font+1)%3;persist();render();$('#app-scroll')?.scrollTo(0,pos);toast(['Chữ lớn — 18px','Chữ rất lớn — 22px','Chữ lớn nhất — 26px'][state.font])},
 family(){family()},'family-next'(){family(1)},'family-finish'(){state.font=Number($('#family-font')?.value||0);state.role='senior';$('#modal').close();screenTo('ask');toast('Xong rồi! Ba mẹ thử gửi câu hỏi đầu tiên nhé.')},install,dictate,
 notifications(){state.unread=0;persist();syncBell();openModal('Thông báo',`${(state.notes||[]).map(noteHTML).join('')}<div class="modal-feature">${avatar('MA','orange','Minh Anh')}<div><strong>Minh Anh đã trả lời câu hỏi của bác</strong><p>“Dạ, bác làm theo 3 bước này nhé…” · 10 phút trước</p><button class="secondary" data-notification-question="1">Xem câu trả lời</button></div></div><div class="modal-feature">${avatar('H','orange','Cô Hương')}<div><strong>Cô Hương muốn kết bạn với bác</strong><p>Cô cũng thích trồng hoa và đọc sách như bác. · 1 giờ trước</p><button class="secondary" data-action="notification-friends">Xem lời mời</button></div></div>`)},
 qr(){openModal('Mở An Vui trên điện thoại',`<div class="qr-modal"><img src="assets/qr-app.svg" alt="Mã QR mở An Vui" width="260" height="260"><p class="qr-url">williamsbui-fnd.github.io/AnVui</p><ol class="qr-steps"><li>Mở <b>Camera</b> và hướng vào mã, chạm vào đường link hiện ra.</li><li>Trên iPhone: bấm nút <b>Chia sẻ</b> trong Safari, chọn <b>Thêm vào MH chính</b>.</li><li>Mở An Vui từ biểu tượng mới trên màn hình, dùng như ứng dụng thật.</li></ol></div><div class="modal-actions"><button class="primary" data-action="close-modal">Xong</button></div>`)},
 'notification-friends'(){$('#modal').close();screenTo('friends')},
 'family-order'(){const p=products.find(p=>p.id===state.productId);state.familyOrder=p.id;persist();openModal('Nhờ con cháu mua giúp',`<div class="modal-feature">${icon('gift')}<div><strong>${p.name}</strong><p>${vnd(p.price)} · ${p.shop}</p></div></div><p class="modal-text">Bác sao chép lời nhắn dưới đây rồi gửi qua Zalo cho con cháu. Con cháu có thể đặt và trả tiền giúp bác.</p><div class="notice" id="share-order-text">Con ơi, ba thấy món “${p.name}” trên An Vui, giá ${vnd(p.price)}. Con xem giúp ba có nên mua không nhé.</div><div class="modal-actions"><button class="secondary" data-action="copy-order">${icon('copy')} Sao chép lời nhắn</button><button class="primary" data-action="family-order-done">Gửi qua Zalo</button></div>`)},
 async 'copy-order'(){try{await navigator.clipboard.writeText($('#share-order-text').textContent);toast('Đã sao chép. Bác dán vào tin nhắn gửi người thân nhé.')}catch{toast('Bác chọn nội dung lời nhắn và sao chép thủ công nhé.')}},
 'family-order-done'(){openModal('Lời nhắn đã sẵn sàng',`<div class="success-block in-modal"><div class="success-icon">${icon('check')}</div><p>Bác mở Zalo, dán lời nhắn vào cuộc trò chuyện với con là xong. An Vui không tự gửi thay bác, để bác luôn chủ động.</p><button class="primary wide" data-action="close-modal">Quay lại sản phẩm</button></div>`)},
 redeem(){if(state.points<200){toast('Bạn cần thêm '+(200-state.points)+' điểm nữa để đổi ưu đãi.');return}state.points-=200;state.redeemed=true;persist();renderScreen();toast('Đã đổi ưu đãi. Gian hàng của bạn sẽ hiển thị nổi bật sau khi được duyệt.')},
 read(){if(!('speechSynthesis'in window)){toast('Trình duyệt này chưa hỗ trợ đọc nội dung. Bác thử tính năng đọc màn hình của điện thoại nhé.');return}window.speechSynthesis.cancel();const text=$('#app-content').innerText;const utterance=new SpeechSynthesisUtterance(text);utterance.lang='vi-VN';utterance.rate=.85;utterance.onerror=()=>toast('Chưa đọc được trên thiết bị này. Bác kiểm tra giọng đọc tiếng Việt nhé.');window.speechSynthesis.speak(utterance);toast('Đang đọc nội dung màn hình…')},
 report(){openModal('Báo cáo hoặc chặn',`<p class="modal-text">Nếu cuộc trò chuyện làm bác không thoải mái, đội ngũ An Vui sẽ xem xét trong vòng 24 giờ. Người bị chặn sẽ không nhắn được cho bác nữa.</p><div class="modal-actions"><button class="secondary" data-action="report-submit">Gửi báo cáo</button><button class="primary" data-action="block-submit">Chặn người này</button></div>`)},
 'report-submit'(){$('#modal').close();toast('Đã gửi báo cáo. Cảm ơn bác đã giúp cộng đồng an toàn hơn.')},'block-submit'(){delete state.messages[state.chatId];state.friends=state.friends.filter(id=>id!==state.chatId);persist();$('#modal').close();screenTo('messages');toast('Đã chặn. Người này sẽ không nhắn được cho bác nữa.')},
 print(){window.print()},'start-pitch'(){state.role='senior';state.view='experience';screenTo('ask');window.scrollTo({top:0,behavior:'smooth'})}
};
document.addEventListener('click',e=>{const el=e.target.closest('button,a[data-action]');if(!el)return;if(el.dataset.action&&el.tagName==='A')e.preventDefault();if(el.disabled)return;if(el.dataset.view){state.view=el.dataset.view;pushNav();render();window.scrollTo({top:0,behavior:'smooth'});return}if(el.dataset.role){switchRole(el.dataset.role);return}if(el.dataset.screen){screenTo(el.dataset.screen);return}if(el.dataset.action){actions[el.dataset.action]?.();return}if(el.dataset.question){state.questionId=Number(el.dataset.question);screenTo('question');return}if(el.classList.contains('live-banner'))el.remove();if(el.dataset.notificationQuestion){state.questionId=Number(el.dataset.notificationQuestion);$('#modal').close();screenTo('question');return}if(el.dataset.liveScreen){$('#modal').close();screenTo(el.dataset.liveScreen);return}if(el.dataset.questionFilter){state.filter=el.dataset.questionFilter;renderScreen();return}if(el.dataset.marketFilter){state.filter=el.dataset.marketFilter;renderScreen();return}if(el.dataset.product){state.productId=el.dataset.product;screenTo('product');return}if(el.dataset.like){const id=el.dataset.like;state.likes=state.likes.includes(id)?state.likes.filter(x=>x!==id):[...state.likes,id];persist();const pos=$('#app-scroll').scrollTop;renderScreen();$('#app-scroll').scrollTop=pos;return}if(el.dataset.helpful){if(state.role!=='senior')return;const id=el.dataset.helpful;if(state.helpful.includes(id)){toast('Bác đã cảm ơn câu trả lời này rồi.');return}state.helpful.push(id);const answer=state.questions.flatMap(q=>q.answers).find(a=>a.id===id);if(answer?.reviewed&&answer.name==='Minh Anh')state.points+=10;persist();const pos=$('#app-scroll').scrollTop;renderScreen();$('#app-scroll').scrollTop=pos;toast(answer?.reviewed?`Cảm ơn bác! ${answer.name} sẽ vui lắm đấy.`:'Cảm ơn bác! Câu trả lời đang được kiểm duyệt.');return}if(el.dataset.friend){const id=el.dataset.friend;if(!state.friends.includes(id))state.friends.push(id);const f=friends.find(f=>f.id===id);if(!state.messages[id])state.messages[id]=[{me:false,text:`Chào bác Minh, rất vui được làm quen với bác!`}];persist();renderScreen();toast(`${f.name} đã đồng ý kết bạn. Bác nhắn tin được rồi.`);return}if(el.dataset.chat){state.chatId=el.dataset.chat;if(!state.messages[state.chatId])state.messages[state.chatId]=[];screenTo('chat');return}if(el.dataset.verify){switchRole(el.dataset.verify);return}if(el.dataset.comment){const p=FEED.find(p=>p.id===el.dataset.comment);const list=COMMENTS[el.dataset.comment]||[];openModal('Bình luận',`${list.length?`<div class="comment-list">${list.map(c=>`<div class="comment">${avatar(c.i,'orange',c.n)}<div><strong>${c.n}</strong><p>${c.t}</p></div></div>`).join('')}</div>`:'<p class="modal-text">Chưa có bình luận nào. Bác là người đầu tiên nhé!</p>'}${p?`<div class="modal-actions"><button class="primary" data-action="notification-friends">${icon('user-plus')} Kết bạn với ${p.name}</button></div>`:''}`);}});
document.addEventListener('input',e=>{if(e.target.id==='question-search'){state.search=e.target.value;$('#question-results').innerHTML=questionList()}if(e.target.id.startsWith('calc-'))updateCalculator()});
document.addEventListener('submit',e=>{const form=e.target;if(!['question-form','answer-form','post-form','chat-form'].includes(form.id))return;e.preventDefault();const fd=new FormData(form);if(form.id==='question-form'){if(state.role!=='senior'){toast('Mục đặt câu hỏi dành cho tài khoản cô bác.');return}const title=String(fd.get('title')).trim(),body=String(fd.get('body')).trim();if(title.length<8||body.length<10){toast('Bác ghi thêm một chút để mọi người hiểu câu hỏi nhé.');return}const id=Date.now();state.questions.unshift({id,name:'Bác Minh',initials:'M',age:68,category:String(fd.get('category')),title,body,time:'Vừa xong',answers:[]});state.questionId=id;persist();screenTo('question');toast('Đã đăng câu hỏi. Bác sẽ được báo ngay khi có người trả lời.');simulateAnswer(id)}if(form.id==='answer-form'){if(state.role!=='helper')return;const body=String(fd.get('body')).trim();if(body.length<15){toast('Bạn viết rõ hơn một chút để cô bác dễ làm theo nhé.');return}const q=state.questions.find(q=>q.id===state.questionId);q.answers.push({id:'answer-'+Date.now(),name:'Minh Anh',initials:'MA',body,likes:0,reviewed:false});persist();renderScreen();openModal('Câu trả lời đang được kiểm duyệt',`<p class="modal-text">Thường mất khoảng 10 phút. Sau khi duyệt, câu trả lời sẽ hiện cho cô bác, và bạn nhận +10 điểm khi cô bác xác nhận đã làm được.</p><div class="modal-actions"><button class="secondary" data-action="close-modal">Đóng</button><button class="primary" id="demo-review-answer">Duyệt ngay (trình diễn)</button></div>`);$('#demo-review-answer').addEventListener('click',()=>{q.answers[q.answers.length-1].reviewed=true;persist();$('#modal').close();renderScreen();toast('Câu trả lời đã được duyệt và hiện công khai.')},{once:true})}if(form.id==='post-form'){if(state.role!=='senior')return;const body=String(fd.get('body')).trim();if(body.length<5)return;state.newPosts.unshift(body);persist();screenTo('home');toast('Đã đăng bài')}if(form.id==='chat-form'){const text=String(fd.get('message')).trim();if(!text)return;state.messages[state.chatId].push({me:true,text});persist();renderScreen();$('#chat-input')?.focus();$('#app-scroll').scrollTop=$('#app-scroll').scrollHeight}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
window.addEventListener('popstate',e=>{const s=e.state;if(!s)return;if($('#modal').open)$('#modal').close();if((s.view||'experience')==='experience')screenTo(s.screen||'home',true);else{state.view=s.view;persist();render();window.scrollTo(0,0)}});
try{history.replaceState({view:state.view,screen:state.screen},'')}catch{}
render();
